const page=await figma.getNodeByIdAsync('2:5');await figma.setCurrentPageAsync(page);figma.skipInvisibleInstanceChildren=false;
const rx=new Map(),hits=[],targets=new Map(),bad=[],untargeted=[],stats={roots:0,nodes:0,reactions:0,actions:0,conditionals:0,starts:0,completed:0,grips:0,frozen:0};const frameIDs=new Set(ALL_ROOTS.map(x=>x[1]));const supported=new Set(['Read the primary source','Choose the seminar theme','Summarize chapter 4']);const destinations=new Set(),aliases=new Set(),vars=new Set();
function reactions(n){if(!rx.has(n.id))rx.set(n.id,n.reactions||[]);return rx.get(n.id)}
function issue(kind,n,root,extra={}){bad.push({kind,node:n.id,name:n.name,root,...extra})}
function ev(x,n,root){if(!x)return;if(x.type==='VARIABLE_ALIAS'){aliases.add(x.value.id);return}if(x.type==='EXPRESSION'){const e=x.value;if(['AND','OR','EQUALS','NOT_EQUAL'].includes(e.expressionFunction)&&e.expressionArguments.length!==2)issue('nonbinary-expression',n,root,{fn:e.expressionFunction,argc:e.expressionArguments.length});for(const a of e.expressionArguments)ev(a,n,root)}}
function actions(list,n,root,depth=0){for(const a of list||[]){stats.actions++;if(a.type==='NODE'&&a.destinationId){destinations.add(a.destinationId);if(a.navigation==='NAVIGATE'&&a.destinationId===root)issue('self-navigation',n,root)}if(a.type==='SET_VARIABLE'){vars.add(a.variableId);ev(a.variableValue,n,root)}if(a.type==='CONDITIONAL'){stats.conditionals++;if(a.conditionalBlocks.length!==1)issue('multi-block-conditional',n,root,{blocks:a.conditionalBlocks.length});if(depth)issue('nested-conditional',n,root);for(const b of a.conditionalBlocks){if(!b.condition)issue('implicit-else',n,root);ev(b.condition,n,root);actions(b.actions,n,root,depth+1)}}}}
const summary=[];
for(const[name,id]of ROOTS){const f=await figma.getNodeByIdAsync(id);if(!f){bad.push({kind:'missing-root',root:id,name});continue}stats.roots++;const nodes=[f,...f.query('FRAME, INSTANCE').toArray()];let nr=0;for(const n of nodes){stats.nodes++;for(const r of reactions(n)){nr++;stats.reactions++;actions(r.actions,n,id)}}
for(const row of f.query('INSTANCE[name^="Task / "]')){const title=row.name.slice(7),comp=row.mainComponent?.id;
if(comp==='3:306'&&supported.has(title)){stats.completed++;const boxes=row.query('INSTANCE[name=Checkbox]').toArray();const box=boxes.find(n=>reactions(n).some(r=>r.trigger?.type==='ON_CLICK'))||boxes[0];if(!box||!reactions(box).some(r=>r.trigger?.type==='ON_CLICK'))issue('supported-completed-no-click',row,id,{title,checkbox:box?.id});}
if(comp!=='3:306'&&comp!=='3:313'){const start=row.query('INSTANCE').toArray().find(n=>n.query('TEXT').toArray().some(t=>t.characters==='Start'));if(start){stats.starts++;if(!reactions(start).some(r=>r.trigger?.type==='ON_CLICK'))issue('row-start-unwired',start,id,{title,row:row.id});}}
if(comp==='3:340'&&title==='Read the primary source'){for(const grip of row.query('FRAME[name="Grip target"]')){stats.grips++;if(grip.width<32||grip.height<32)issue('small-read-grip',grip,id,{width:grip.width,height:grip.height});if(!reactions(grip).some(r=>r.trigger?.type==='ON_DRAG'))untargeted.push({root:id,grip:grip.id,row:row.id});}}
}
for(const row of f.query('INSTANCE[name^="Frozen task / "]')){stats.frozen++;for(const n of[row,...row.query('FRAME, INSTANCE').toArray()])if(reactions(n).length)issue('frozen-row-action',n,id,{row:row.id})}
summary.push({id,name,inspectedNodes:nodes.length,reactions:nr});}
for(const id of destinations){let n=await figma.getNodeByIdAsync(id);if(!n){bad.push({kind:'missing-destination',target:id});continue}let p=n;while(p&&p.type!=='PAGE')p=p.parent;if(p?.id!=='2:5')bad.push({kind:'cross-page-destination',target:id,page:p?.id});targets.set(id,n.name);}
return {summary,stats,issues:bad,unwiredRepresentativeGrips:untargeted,destinationCount:destinations.size,destinationIds:[...destinations],setVariableCount:vars.size,aliasCount:aliases.size,flowStarts:page.flowStartingPoints};
